begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(15);
insert into auth.users(id,email) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a@local.test'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','b@local.test');
create function public.test_event(id uuid,title text default '读书') returns jsonb language sql as $$select jsonb_build_object('table','events','id',id,'userId','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','version',0,'updatedAt',now(),'deletedAt',null,'title',title,'notes','','plannedDate','2026-10-17','startAt',null,'endAt',null,'durationMinutes',30,'location',null,'categoryId',null,'locked',false,'completedAt',null,'reviewItemId',null,'recurrenceId',null,'occurrenceDate',null,'travelMode','walking')$$;
create function public.test_op(changes jsonb,id uuid default gen_random_uuid()) returns jsonb language sql as $$select jsonb_build_object('id',id,'userId','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','command',jsonb_build_object('kind','write','changes',changes))$$;
create function public.test_change(value jsonb,version int default 0) returns jsonb language sql as $$select jsonb_build_object('table',value->>'table','id',value->>'id','baseVersion',version,'value',value)$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select is(apply_operation(test_op(jsonb_build_array(test_change(test_event('11111111-1111-4111-8111-111111111111'))),'22222222-2222-4222-8222-222222222222'))->>'status','applied','create own event');
select is(apply_operation(test_op(jsonb_build_array(test_change(test_event('11111111-1111-4111-8111-111111111111'))),'22222222-2222-4222-8222-222222222222'))->'batch'->>'cursor','1','duplicate operation id returns same receipt');
select is((select version::int from records where id='11111111-1111-4111-8111-111111111111'),1,'duplicate does not increment');
select is(apply_operation(test_op(jsonb_build_array(test_change(test_event('11111111-1111-4111-8111-111111111111','旧设备')))))->>'status','conflict','stale edit conflicts');
select is((select payload->>'title' from records where id='11111111-1111-4111-8111-111111111111'),'读书','conflict cannot overwrite');
select throws_ok($q$update records set payload='{}'$q$,'42501',null,'direct writes forbidden');
select throws_ok($q$select apply_operation(test_op(jsonb_build_array(test_change(test_event('33333333-3333-4333-8333-333333333333')||'{"durationMinutes":0}'))))$q$,'22023',null,'invalid duration rejected');
select throws_ok($q$select apply_operation(test_op(jsonb_build_array(test_change(test_event('33333333-3333-4333-8333-333333333333'))))||'{"userId":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}')$q$,'22023',null,'cannot impersonate');
select is(apply_operation(test_op(jsonb_build_array(test_change(test_event('33333333-3333-4333-8333-333333333333')),test_change(test_event('11111111-1111-4111-8111-111111111111')))))->>'status','conflict','batch conflict atomic');
select is((select count(*)::int from records where id='33333333-3333-4333-8333-333333333333'),0,'batch did not partly apply');
select is(jsonb_array_length(pull_changes(0,1)->'batches'),1,'complete batch page');
select is((pull_changes(0,1)->>'hasMore')::boolean,false,'no fake pages');
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
select is((select count(*)::int from records),0,'other account cannot read');
select is(jsonb_array_length(pull_changes(0,10)->'batches'),0,'other account cannot pull commits');
set local role anon;
select throws_ok($q$select pull_changes(0,1)$q$,'42501',null,'anonymous cannot invoke sync');
select * from finish();rollback;
